import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type RingTimerProps = Record<string, any>;

const RingTimer: React.FC<RingTimerProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 13,
  ringColor = "#ff4757",
  ringTrackColor = "#2f3542",
  textColor = "#ffffff",
  strokeWidth = 40,
  timerSize = 600,
}) => {
  useFontLoader(["Inter", "Roboto Mono"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? "#00000000" : backgroundColor;

  // Animation Logic
  const durationInFrames = durationInSeconds * fps;
  const progress = interpolate(frame, [0, durationInFrames], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Calculate Geometry
  const radius = (timerSize - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  
  // Ring depletes: Full (0 offset) -> Empty (circumference offset)
  const strokeDashoffset = interpolate(
    progress,
    [0, 1],
    [0, circumference],
    { extrapolateRight: "clamp" }
  );

  // Countdown Number
  // We want it to show durationInSeconds at frame 0, and 0 at the end.
  // Using ceil to show whole seconds nicely.
  const timeLeft = Math.ceil(
    interpolate(frame, [0, durationInFrames], [durationInSeconds, 0], {
      extrapolateRight: "clamp",
    })
  );

  // Responsive Centering
  const centerX = width / 2;
  const centerY = height / 2;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          transform: "rotate(-90deg)", // Start from top
          transformOrigin: "center",
        }}
      >
        {/* Track Circle */}
        <circle
          cx={centerX}
          cy={centerY}
          r={radius}
          fill="none"
          stroke={ringTrackColor}
          strokeWidth={strokeWidth}
          opacity={0.3}
        />
        {/* Animated Ring */}
        <circle
          cx={centerX}
          cy={centerY}
          r={radius}
          fill="none"
          stroke={ringColor}
          strokeWidth={strokeWidth}
          strokeDasharray={circumference}
          strokeDashoffset={strokeDashoffset}
          strokeLinecap="round"
        />
      </svg>

      {/* Timer Text */}
      <div
        style={{
          position: "absolute",
          top: centerY - timerSize / 4, // Rough vertical centering adjustment
          left: centerX - timerSize / 2,
          width: timerSize,
          height: timerSize / 2,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          fontFamily: "Roboto Mono, monospace",
          fontWeight: 700,
          fontSize: timerSize * 0.35,
          color: textColor,
          textAlign: "center",
          transition: "none",
        }}
      >
        {timeLeft}
      </div>
    </AbsoluteFill>
  );
};

export default RingTimer;